 function proof(fence:any,mode:'genesis'|'advance'='genesis',previous:any=null){const fake=(role:string,label:string)=>({role,id:h(label),sha256:h(label),byteLength:1}),body={schema:'osv-mcp.q2.c3b.prepared-checkpoint.v1',api:'PrepareCheckpoint',lineage,fence,mode,previous,snapshot:fake('snapshot','snapshot'+evidence.size),head:{format:'v2',revision:evidence.size+1,commitDigest:h('commit'+evidence.size),stateRoot:h('state'+evidence.size),baseDigest:h('base')},inventoryDigest:h('inventory')},wire=signRegistryTest(body,'checkpoint-issuer-reply','control','control.PrepareCheckpoint','reply',f.registry),ref={...publicRecordRef(wire),role:'checkpoint-prepare'};evidence.set(ref.sha256,wire);return ref;}
 function drained(barrier:any,role:string){const identity=f.registry.credentials.find((c:any)=>c.identity.credentialId===role+'-request').identity,body={schema:'osv-mcp.q2.c3b.cooperative-drained.v1',api:'ConfirmFenced',barrier,subject:identity.instanceId,boot:identity.boot,inFlight:0,effects:0,scope:'cooperative-only'},wire=signRegistryTest(body,role+'-request','control','control.ConfirmFenced','request',f.registry),ref={...publicRecordRef(wire),role:'fence-evidence'};evidence.set(ref.sha256,wire);return ref;}
 return {root,f,keys,hooks,evidence,environment:env,lineage,clientFloor:(role:string)=>floorFor(role).snapshot(),setAnchorFloor:(floor:any)=>anchorFloor=structuredClone(floor),start,disk,call,retry,proof,drained,signer,rolePlan,get registry(){return registry;},get anchor(){return anchor;},get stores(){return stores;},get registryClients(){return clients;},tick(n:number){now+=n;},revoke(){allowed=false;},closeOwner(){open=false;},async stop(){for(const c of clients.values())c.close();clients.clear();session?.close();for(const s of stores.splice(0))s.close();},async restart(){await this.stop();for(const role of ['control-anchor','lineage-registry']){const boot=randomBytes(32).toString('hex');f.configs.find(c=>c.role===role).boot=boot;for(const c of f.registry.credentials)if(c.identity.role===role)c.identity.boot=boot;}await start();},async cleanup(){for(const c of clients.values())c.close();session?.close();for(const s of stores.splice(0))try{s.close();}catch{}await rm(root,{recursive:true,force:true});}};
